import Foundation
import JavaScriptCore
import Testing
@testable import Aresium

/// The small fictional list is generated by aresium's own packer (scripts/98-local-places-fixture.mjs).
@MainActor
struct PackedLocalPlacesTests {
    private let auth = BackendAuth(token: nil)
    private let payment = SortingPayment(counterparty: "Quarzfunken", description: "Fictional purchase", source: "bank",
                                         account: "fictional", amount: -12, currency: "EUR", date: "2026-10-01")

    private func fixture() throws -> PackedLocalPlaces {
        try PackedLocalPlaces.inflate(PhoneTest.fixture("local-places-fixture.places.bin.gz").data)
    }

    private func engine() async throws -> AresiumEngine {
        let engine = try PhoneTest.engine()
        try await engine.setLocalPlaces(fixture())
        return engine
    }

    @Test func actualNoCopyBufferOptInClearingAndReloading() async throws {
        let url = try #require(AresiumEngine.bundledScriptURL())
        let script = try String(contentsOf: url, encoding: .utf8) + """
        ;(() => {
            const original = AresiumEngine;
            globalThis.AresiumEngine = { ...original, setLocalPlaces: buffer => {
                if (buffer !== null && !(buffer instanceof ArrayBuffer)) throw new Error('Expected an actual ArrayBuffer');
                globalThis.__fixtureBuffer = buffer;
                original.setLocalPlaces(buffer);
            }};
        })();
        """
        let engine = try AresiumEngine(script: script)
        let places = try fixture()
        try await engine.setLocalPlaces(places)
        // Check the actual backing address, not just an equal result after a hidden copy.
        let context = try #require(Mirror(reflecting: engine).children.first { $0.label == "context" }?.value as? JSContext)
        try autoreleasepool {
            let value = try #require(context.objectForKeyedSubscript("__fixtureBuffer"))
            let object = try #require(JSValueToObject(context.jsGlobalContextRef, value.jsValueRef, nil))
            #expect(JSObjectGetArrayBufferBytesPtr(context.jsGlobalContextRef, object, nil) == places.bytes)
            #expect(JSObjectGetArrayBufferByteLength(context.jsGlobalContextRef, object, nil) == places.count)
        }
        #expect(try await engine.sortPayments([payment], categories: ["groceries"], learned: [:])
                == [SortResult(categoryId: nil, source: nil)])
        #expect(try await engine.sortPayments([payment], categories: ["groceries"], learned: [:], localPlaces: true)
                == [SortResult(categoryId: "groceries", source: "starter")])
        #expect(try await engine.sortPayments([payment], categories: ["hobbies"], learned: [:], localPlaces: true)
                == [SortResult(categoryId: nil, source: nil)])
        try await engine.setLocalPlaces(nil)
        #expect(try await engine.sortPayments([payment], categories: ["groceries"], learned: [:], localPlaces: true)
                == [SortResult(categoryId: nil, source: nil)])
        try await engine.setLocalPlaces(fixture())
        #expect(try await engine.sortPayments([payment], categories: ["groceries"], learned: [:], localPlaces: true)
                == [SortResult(categoryId: "groceries", source: "starter")])
    }

    @Test func simultaneousContextsShareNativeBytesAndClearIndependently() async throws {
        let directory = PhoneTest.storage().root
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let url = directory.appending(path: "fixture.gz")
        try PhoneTest.fixture("local-places-fixture.places.bin.gz").data.write(to: url)
        let cache = PackedLocalPlacesCache()
        let recording = PickerTiming.Recording()
        let (one, two) = try await PickerTiming.$recording.withValue(recording) {
            async let first = cache.read(url)
            async let second = cache.read(url)
            return try await (first, second)
        }
        #expect(one === two)
        let loads = recording.values.filter { $0.name == "localPlaces.load" }
        #expect(loads.count == 1 && loads.first?.kind == "worker", "One native read/inflate, off main")
        try FileManager.default.removeItem(at: url)
        #expect(try await cache.read(url) === one, "An active shared buffer is reused without another file read")
        let person = try PhoneTest.engine()
        let tour = try PhoneTest.engine()
        try await person.setLocalPlaces(one)
        try await tour.setLocalPlaces(two)
        try await person.setLocalPlaces(nil)
        #expect(try await person.sortPayments([payment], categories: ["groceries"], learned: [:], localPlaces: true)
                == [SortResult(categoryId: nil, source: nil)])
        #expect(try await tour.sortPayments([payment], categories: ["groceries"], learned: [:], localPlaces: true)
                == [SortResult(categoryId: "groceries", source: "starter")])
    }

    @Test func invalidGzipAndPackedReplacementAreRefused() async throws {
        let compressed = try PhoneTest.fixture("local-places-fixture.places.bin.gz").data
        var badCRC = compressed
        badCRC[badCRC.count - 8] ^= 0xff
        for bytes in [Data(), Data(repeating: 0, count: 18), Data(compressed.dropLast()), badCRC] {
            #expect(throws: CocoaError.self) { try PackedLocalPlaces.inflate(bytes) }
        }
        let engine = try await engine()
        let invalid = try fixture()
        invalid.bytes.storeBytes(of: UInt32(0), as: UInt32.self) // Corrupt the fresh fixture's magic before installing.
        await #expect(throws: EngineError.self) { try await engine.setLocalPlaces(invalid) }
        #expect(try await engine.sortPayments([payment], categories: ["groceries"], learned: [:], localPlaces: true)
                == [SortResult(categoryId: "groceries", source: "starter")])
    }

    @Test func phoneImportPickerDryRunSortAndLearningUseTheList() async throws {
        let phone = try await PhoneCountingTests.backend(engine: engine())
        _ = try await phone.importFiles([PhoneTest.vrBank([
            ("01.10.2026", "Quarzfunken", "Fictional purchase", -1200),
        ])], auth: auth)
        #expect(phone.summary.unsorted == 1)
        #expect(try await phone.categoryCounts()["groceries"] == 1, "The picker's dry run uses local places")
        try await phone.choose("groceries")
        let first = try #require(try await phone.ledger.payments().first)
        #expect(first.category == "groceries" && first.categorySource == .starter)
        try await phone.choose("hobbies")
        _ = try await phone.switchCategory(id: first.id, to: "Hobbies", auth: auth)
        _ = try await phone.importFiles([PhoneTest.vrBank([
            ("02.10.2026", "Quarzfunken", "Fictional purchase", -1800),
        ], name: "next.csv")], auth: auth)
        let payments = try await phone.ledger.payments()
        #expect(payments.map(\.category) == ["hobbies", "hobbies"])
        #expect(payments.map(\.categorySource) == [.manual, .learned], "Learning wins over the listed shop")
    }

    @Test func structuralRulesStayAheadOfLearningAndLocalPlaces() async throws {
        let engine = try await engine()
        var out = payment
        out.accountIban = "DE89370400440532013000"
        out.counterpartyIban = "DE02120300000000202051"
        out.description = "Umbuchung"
        var incoming = out
        incoming.account = "fictional-second"
        incoming.accountIban = out.counterpartyIban
        incoming.counterpartyIban = out.accountIban
        incoming.amount = 12
        let rules = try await engine.learn(out, categoryID: "hobbies")
        #expect(try await engine.sortPayments([out, incoming], categories: ["groceries", "hobbies"],
                                              learned: rules, localPlaces: true)
                == Array(repeating: SortResult(categoryId: "own-transfers", source: "structural"), count: 2))
    }

    @Test func serverImportSendsOnlyTheExistingFilesContract() async throws {
        let transport = RoutedTransport()
        transport.answer("POST /api/import", 200, ["results": []])
        let server = ServerBackend(client: APIClient(transport: transport))
        let files = [PhoneTest.vrBank([("01.10.2026", "Quarzfunken", "Fictional purchase", -1200)])]
        _ = try await server.importFiles(files, auth: BackendAuth(token: "fictional-token"))
        let request = try #require(transport.requests.first)
        #expect(transport.requests.count == 1)
        let body = try #require(request.httpBody)
        let json = try #require(JSONSerialization.jsonObject(with: body) as? [String: Any])
        #expect(Set(json.keys) == ["files"])
        let sent = try #require(json["files"] as? [[String: Any]])
        #expect(sent.count == 1)
        let file = try #require(sent.first)
        #expect(Set(file.keys) == ["name", "content"])
        #expect(file["name"] as? String == files[0].name)
        #expect(file["content"] as? String == files[0].content)
    }

    @Test func localPlacesLicenceHasAttributionLinksAndGerman() throws {
        let english = AppLanguage.$scoped.withValue(.english) { BundledLicence.localPlaces() }
        let german = AppLanguage.$scoped.withValue(.german) { BundledLicence.localPlaces() }
        #expect(english.name == "© OpenStreetMap contributors")
        #expect(german.name == "© OpenStreetMap-Mitwirkende")
        #expect(german.purpose == "Lokale Orte zum Sortieren")
        #expect(english.licenceName == "ODbL 1.0")
        let text = try #require(english.text())
        #expect(text.contains("© OpenStreetMap contributors") && text.contains("Open Database License (ODbL) 1.0"))
        #expect(english.links.map(\.url.absoluteString) == ["https://www.openstreetmap.org/copyright",
            "https://opendatacommons.org/licenses/odbl/1-0/", "https://aresium.de/osm/local-places-de.places.bin.gz"])
        #expect(english.links.allSatisfy { text.contains($0.url.absoluteString) })
        #expect(german.links.map(\.title) == ["OpenStreetMap: Urheberrecht und Mitwirkende",
            "Open Database License (ODbL) 1.0", "Liste der lokalen Orte herunterladen"])
    }
}
